from fastapi import FastAPI
from pydantic import BaseModel, computed_field
from fastapi.openapi.utils import get_openapi
import json

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str
    @computed_field
    @property
    def description(self) -> str:
        return f"Description of {self.name}"

@app.get("/item", response_model=Item)
def read_item():
    return Item(name="test")

openapi_schema = get_openapi(app, *, separate_input_output_schemas=False)
print(json.dumps(openapi_schema, indent=2))

# Check if 'description' is in the schema for Item
item_schema = openapi_schema["components"]["schemas"]["Item"]
if "description" in item_schema.get("properties", {}):
    print("Computed field 'description' is present in the schema.")
else:
    print("Computed field 'description' is MISSING from the schema.")

# Now try with separate_input_output_schemas=True
app_separate = FastAPI(separate_input_output_schemas=True)
@app_separate.get("/item", response_model=Item)
def read_item_separate():
    return Item(name="test")

openapi_schema_separate = get_openapi(app_separate, *, separate_input_output_schemas=True)
item_schema_separate = openapi_schema_separate["components"]["schemas"]["Item"]
# When separate_input_output_schemas=True, it should be Item (for input) and Item (for output)
# Actually, it might be Item and Item_out or something.
# Let's see what's in the schemas.
print("Schemas with separate_input_output_schemas=True:", openapi_schema_separate["components"]["schemas"].keys())
for schema_name, schema in openapi_schema_separate["components"]["schemas"].items():
    if "description" in schema.get("properties", {}):
        print(f"Computed field 'description' is present in schema {schema_name}.")

